css:
@page {
  size: A4;
  margin: 0;
}

.print-format {
  padding: 0 !important;
  margin: 0 !important;
  margin-top: 0mm !important;
  margin-bottom: 0mm !important;
  margin-left: 0mm !important;
  margin-right: 0mm !important;
  min-height: 0 !important;
  max-width: none !important;
}

.action-banner {
  display: none !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  overflow: hidden !important;
}

.print-format-gutter {
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
}

.print-format-preview {
  padding: 0 !important;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  margin: 0;
  padding: 0;
}

.print-page {
  width: 210mm;
  height: 297mm;
  position: relative;
  overflow: hidden;

  background-image: var(--page-bg);
  background-repeat: no-repeat;
  background-position: center center;
  background-size: 210mm 297mm;

  page-break-after: always;
}

.print-page:last-child {
  page-break-after: auto;
}

.field {
  position: absolute;
  font-size: 10px;
  line-height: 1.25;
  color: #000;
  white-space: normal;
}

.field-supplier-name {
  top: 67mm;
  left: 19mm;
  width: 90mm;
}

.field-supplier-address {
  top: 72mm;
  left: 19mm;
  width: 95mm;
  min-height: 15mm;
}

.field-bill-no {
  top: 90.5mm;
  left: 40mm;
  width: 30mm;
}

.field-remark {
  top: 99mm;
  left: 40mm;
  width: 70mm;
}

.field-document-name {
  top: 62mm;
  left: 143mm;
  width: 56mm;
}

.field-posting-date {
  top: 70mm;
  left: 143mm;
  width: 56mm;
}

.field-po-no {
  top: 88mm;
  left: 122mm;
  width: 48mm;
}

.field-po-date {
  top: 88mm;
  left: 181mm;
  width: 24mm;
}

.field-delivery-by {
  top: 91.5mm;
  left: 144mm;
  width: 52mm;
}

.item-table-wrapper {
  position: absolute;
  top: 118mm;
  left: 14mm;
  width: 188mm;
}

.item-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 9px;
  color: #000;
}

.item-table th,
.item-table td {
  border: none;
  padding: 1.5mm;
  vertical-align: top;
  line-height: 1.25;
}

.col-no {
  width: 11mm;
  text-align: center;
}

.col-item {
  width: 92mm;
  text-align: left;
}

.col-qty {
  width: 30mm;
  text-align: right;
}

.col-rate {
  width: 25mm;
  text-align: right;
}

.col-amount {
  width: 30mm;
  text-align: right;
}

.field-gross-amount {
  top: 210mm;
  left: 162mm;
  width: 38mm;
  text-align: right;
}

.field-less-discount {
  top: 217mm;
  left: 162mm;
  width: 38mm;
  text-align: right;
}

.field-after-discount {
  top: 222.5mm;
  left: 162mm;
  width: 38mm;
  text-align: right;
}

.field-less-deposit {
  top: 230mm;
  left: 162mm;
  width: 38mm;
  text-align: right;
}

.field-after-deposit {
  top: 236.5mm;
  left: 162mm;
  width: 38mm;
  text-align: right;
}

.field-vat {
  top: 244mm;
  left: 162mm;
  width: 38mm;
  text-align: right;
}

.field-total-amount {
  top: 251mm;
  left: 162mm;
  width: 38mm;
  text-align: right;
  font-weight: bold;
}

html:
{% set background = "/assets/connect_diagnostics_core/images/print_formats/goods-receipt-1.png" %}

{% set purchase_orders = [] %}
{% for row in doc.items %}
  {% if row.purchase_order and row.purchase_order not in purchase_orders %}
    {% set _ = purchase_orders.append(row.purchase_order) %}
  {% endif %}
{% endfor %}

{% set po_dates = [] %}
{% for po in purchase_orders %}
  {% set po_date = frappe.db.get_value("Purchase Order", po, "transaction_date") %}
  {% if po_date %}
    {% set _ = po_dates.append(format_date(po_date)) %}
  {% endif %}
{% endfor %}

  <div
    class="print-page"
    style="--page-bg: url('{{ background }}');"
  >

    <!-- Supplier -->
    <div class="field field-supplier-name">
      {{ doc.supplier_name or doc.supplier or "" }}
    </div>

    <div class="field field-supplier-address">
      {{ (doc.address_display or "") | safe }}
    </div>

    <!-- Bill / Remark -->
    <div class="field field-bill-no">
      {{ doc.supplier_delivery_note or "" }}
    </div>

    <div class="field field-remark">
      {{ doc.remarks or "" }}
    </div>

    <!-- Document info -->
    <div class="field field-document-name">
      {{ doc.name }}
    </div>

    <div class="field field-posting-date">
      {{ format_date(doc.posting_date) }}
    </div>

    <div class="field field-po-no">
      {{ purchase_orders | join(", ") }}
    </div>

    <div class="field field-po-date">
      {{ po_dates | join(", ") }}
    </div>

    <div class="field field-delivery-by">
      {{ doc.transporter_name or "" }}
    </div>

    <!-- Item table -->
    <div class="item-table-wrapper">
      <table class="item-table">
        <tbody>
          {% for row in doc.items %}
            <tr>
              <td class="col-no">
                {{ loop.index }}
              </td>

              <td class="col-item">
                {{ row.item_code }} : {{ row.item_name }}
              </td>

              <td class="col-qty">
                {{ frappe.format(row.qty, {"fieldtype": "Float"}) }}
              </td>

              <td class="col-rate">
                {{ print_currency(row.rate + (row.discount_amount if row.discount_amount > 0 else 0), doc.currency) }}
              </td>

              <td class="col-amount">
                {{ print_currency(row.amount, doc.currency) }}
              </td>
            </tr>
          {% endfor %}
        </tbody>
      </table>
    </div>

    <!-- Totals -->
    <div class="field field-gross-amount">
      {{ print_currency(doc.total or 0, doc.currency) }}
    </div>

    <div class="field field-less-discount">
      {{ print_currency(doc.discount_amount or 0, doc.currency) }}
    </div>

    <div class="field field-after-discount">
      {{ print_currency(doc.net_total or 0, doc.currency) }}
    </div>

    <div class="field field-less-deposit">
      {{ print_currency(0, doc.currency) }}
    </div>

    <div class="field field-after-deposit">
      {{ print_currency(doc.net_total or 0, doc.currency) }}
    </div>

    <div class="field field-vat">
      {{ print_currency(doc.total_taxes_and_charges or 0, doc.currency) }}
    </div>

    <div class="field field-total-amount">
      {{ print_currency(doc.grand_total or 0, doc.currency) }}
    </div>

  </div>
